+  </div>
+  <div class="wz-bar"><div class="wz-bar-fill" id="wz-bar"></div></div>
+  <div class="wz-body">
+    <div class="q-idx" id="q-idx">[01]</div>
+    <h2 class="q-title" id="q-title"></h2>
+    <p class="q-hint" id="q-hint"></p>
+    <div id="q-input"></div>
+    <div class="err-msg" id="q-error"></div>
+  </div>
+  <div class="wz-nav">
+    <button class="btn-back" id="btn-back" onclick="prevQ()">← Anterior</button>
+    <button class="btn-gold" id="btn-next" style="animation:none" onclick="nextQ()">Siguiente →</button>
+  </div>
+</section>
+
+<!-- ============ ANALYZING ============ -->
+<section class="screen" id="screen-analyzing">
+  <div class="eyebrow">Generando diagnóstico</div>
