+</section>
+
+<!-- ============ RESULT ============ -->
+<section class="screen" id="screen-result">
+  <div class="res-hero">
+    <div class="eyebrow">Metacrypto Club · Diagnóstico de Portfolio</div>
+    <h1>Tu diagnóstico<br><em>está listo.</em></h1>
+  </div>
+  <div class="res-wrap" id="res-content"></div>
+  <footer id="res-footer"></footer>
+</section>
+
+<script>
+/* ================= CONFIG (SPEC §4 — parametrizable) ================= */
+const CONFIG = {
+  brand: "Metacrypto Club",
+  ctaText: "Agendar llamada estratégica",
+  ctaUrl: "#cta",              // TODO: Calendly o WhatsApp (SPEC §11.7)
+  videoUrl: null,              // TODO: URL video regalo (SPEC §11.6)
+  hotLeadMinUSD: 25000         // umbral lead caliente (SPEC §11.1) — mock
+};
+
+const RANGES_CAPITAL = ["Menos de 1.000 $","1.000 – 5.000 $","5.000 – 25.000 $","25.000 – 100.000 $","Más de 100.000 $"];
+const RANGES_MONTHLY = ["0 $","Menos de 500 $","500 – 2.000 $","2.000 – 10.000 $","Más de 10.000 $"];
+const rangeMid = i => [500,3000,15000,62500,150000][i] ?? 0;
+const rangeMidM = i => [0,250,1250,6000,15000][i] ?? 0;
+
+/* ================= WIZARD DATA (SPEC RF-2) ================= */
+const QUESTIONS = [
+  { key:"capital", title:"¿Cuánto capital tienes invertido actualmente en cripto?",
+    hint:"Una estimación es suficiente. Nadie verá este dato salvo nuestro equipo.",
+    type:"options", options:RANGES_CAPITAL },
+  { key:"cash", title:"¿Cuánto dinero tienes disponible en efectivo o stablecoins, listo para invertir?",
+    hint:"Cuenta lo que tienes parado: dentro o fuera de exchanges. USDT, USDC, dólares, euros…",
+    type:"options", options:RANGES_CAPITAL },
+  { key:"monthly", title:"¿Qué aportación mensual podrías mantener los próximos 12 meses?",
+    hint:"Sin compromiso. Solo para dimensionar tu plan.",
+    type:"options", options:RANGES_MONTHLY },
+  { key:"risk", title:"¿Cuál es tu perfil de riesgo?",
+    hint:"Sé honesto: no es lo que te gustaría ser, es cómo reaccionas cuando el mercado cae un 20%.",
+    type:"options", options:["Muy agresivo","Agresivo","Moderado","Conservador","Muy conservador"] },
+  { key:"experience", title:"¿Cuánta experiencia tienes invirtiendo en cripto?",
+    hint:"",
+    type:"options", options:["Ninguna, empiezo de cero","Menos de 1 año","Entre 1 y 3 años","Más de 3 años"] },
+  { key:"portfolio", title:"¿Cómo se distribuye tu portfolio actual?",
+    hint:"Reparte el 100% como lo tengas hoy. Si aún no has invertido, ponlo todo en «Sin invertir».",
+    type:"portfolio" },
+  { key:"altcoins", title:"¿En cuántas altcoins distintas estás invertido?",
+    hint:"Sin contar Bitcoin, Ethereum ni stablecoins.",
+    type:"options", options:["1 – 2","3 – 5","6 – 10","Más de 10"],
+    skipIf: d => (d.portfolio.alt || 0) === 0 },
+  { key:"concern", title:"¿Cuál es tu mayor preocupación ahora mismo con tus inversiones?",
+    hint:"Opcional, pero cuanto más contexto, más afilado el diagnóstico.",
+    type:"text" },
+  { key:"contact", title:"¿Dónde te enviamos el diagnóstico completo?",
+    hint:"Lo verás en pantalla en unos segundos. Te enviaremos también una copia y el acceso al video exclusivo.",
+    type:"contact" },
+];
+
+/* ================= STATE ================= */
+let step = 0;
+const data = { portfolio:{ btc:0, eth:0, stables:0, alt:0, fiat:0 } };
+
+/* ================= NAVIGATION ================= */
+function show(id){
+  document.querySelectorAll(".screen").forEach(s=>s.classList.remove("active"));
+  document.getElementById(id).classList.add("active");
+  window.scrollTo(0,0);
+}
+function startWizard(){ step = 0; renderQ(); show("screen-wizard"); }
+
+function visibleQuestions(){
+  return QUESTIONS.filter(q => !q.skipIf || !q.skipIf(data));
+}
+
+function renderQ(){
+  const qs = visibleQuestions();
+  const q = qs[step];
+  const total = QUESTIONS.length;
+  const num = QUESTIONS.indexOf(q) + 1;
+  document.getElementById("q-idx").textContent = `[${String(num).padStart(2,"0")}]`;
+  document.getElementById("q-title").textContent = q.title;
+  document.getElementById("q-hint").textContent = q.hint || "";
+  document.getElementById("wz-progress").textContent = `Pregunta ${String(num).padStart(2,"0")} / ${String(total).padStart(2,"0")}`;
+  document.getElementById("wz-bar").style.width = `${(num/total)*100}%`;
+  document.getElementById("btn-back").disabled = step === 0;
+  document.getElementById("btn-next").textContent = step === qs.length-1 ? "Ver mi diagnóstico →" : "Siguiente →";
+  hideErr();
+
+  const box = document.getElementById("q-input");
+  box.innerHTML = "";
+
+  if(q.type === "options"){
+    const wrap = document.createElement("div"); wrap.className = "opts";
+    q.options.forEach((opt,i)=>{
+      const b = document.createElement("button");
+      b.className = "opt" + (data[q.key]===i ? " sel":"");
+      b.innerHTML = `<span class="dot"></span><span>${opt}</span>`;
+      b.onclick = ()=>{ data[q.key]=i; wrap.querySelectorAll(".opt").forEach(x=>x.classList.remove("sel")); b.classList.add("sel"); setTimeout(nextQ,220); };
+      wrap.appendChild(b);
+    });
+    box.appendChild(wrap);
+  }
+
+  if(q.type === "portfolio"){
+    const rows = [["btc","Bitcoin","El activo refugio del mercado"],["eth","Ethereum","La capa de smart contracts"],
+      ["stables","Stablecoins","USDT, USDC… dentro de exchanges"],["alt","Otras altcoins","Todo lo demás: SOL, XRP, memecoins…"],
+      ["fiat","Sin invertir","Fiat parado en el banco o en cuenta"]];
+    const t = document.createElement("div"); t.className = "pf-table";
+    rows.forEach(([k,label,note])=>{
+      const r = document.createElement("div"); r.className = "pf-row";
+      r.innerHTML = `<label>${label}<small>${note}</small></label>
+        <div class="pf-input"><input type="number" min="0" max="100" step="1" value="${data.portfolio[k]}" data-k="${k}"><span>%</span></div>`;
+      t.appendChild(r);
+    });
+    const tot = document.createElement("div"); tot.className = "pf-total";
+    tot.innerHTML = `<span>Total repartido</span><b id="pf-total-v">0%</b>`;
+    t.appendChild(tot);
+    box.appendChild(t);
+    const upd = ()=>{
+      let sum = 0;
+      t.querySelectorAll("input").forEach(inp=>{ const v = Math.max(0, Math.min(100, +inp.value || 0)); data.portfolio[inp.dataset.k] = v; sum += v; });
+      const el = document.getElementById("pf-total-v");
+      el.textContent = sum + "%";
+      el.className = sum === 100 ? "" : "bad";
+    };
+    t.querySelectorAll("input").forEach(inp=>inp.addEventListener("input",upd));
+    upd();
+  }
+
+  if(q.type === "text"){
+    const ta = document.createElement("textarea");
+    ta.className = "freetext"; ta.maxLength = 280;
+    ta.placeholder = "Ej.: «Compré en máximos y no sé si aguantar, vender o promediar…»";
+    ta.value = data[q.key] || "";
+    ta.oninput = ()=> data[q.key] = ta.value;
+    box.appendChild(ta);
+  }
+
+  if(q.type === "contact"){
+    box.innerHTML = `
+      <div class="field"><label>Nombre</label><input id="f-name" type="text" placeholder="Tu nombre" value="${data.name||""}"></div>
+      <div class="field"><label>Teléfono (WhatsApp)</label><input id="f-phone" type="tel" placeholder="+34 600 000 000" value="${data.phone||""}"></div>
+      <div class="field"><label>Email</label><input id="f-email" type="email" placeholder="tu@email.com" value="${data.email||""}"></div>
+      <label class="consent"><input id="f-consent" type="checkbox" ${data.consent?"checked":""}>
+        <span>Acepto recibir mi diagnóstico y comunicaciones de ${CONFIG.brand}. Puedo darme de baja cuando quiera. Esto no constituye asesoramiento financiero.</span></label>`;
+  }
+}
+
+function showErr(m){ const e=document.getElementById("q-error"); e.textContent = m; e.style.display="block"; }
+function hideErr(){ document.getElementById("q-error").style.display="none"; }
+
+function validate(){
+  const q = visibleQuestions()[step];
+  if(q.type === "options" && data[q.key] === undefined){ showErr("Elige una opción para continuar."); return false; }
+  if(q.type === "portfolio"){
+    const sum = Object.values(data.portfolio).reduce((a,b)=>a+b,0);
+    if(sum !== 100){ showErr(`Los porcentajes deben sumar 100% (ahora: ${sum}%).`); return false; }
+  }
+  if(q.type === "contact"){
+    data.name = document.getElementById("f-name").value.trim();
+    data.phone = document.getElementById("f-phone").value.trim();
+    data.email = document.getElementById("f-email").value.trim();
+    data.consent = document.getElementById("f-consent").checked;
+    if(!data.name){ showErr("Dinos al menos tu nombre."); return false; }
+    if(!data.phone){ showErr("Necesitamos tu teléfono para enviarte el acceso."); return false; }
+    if(!/.+@.+\..+/.test(data.email)){ showErr("Ese email no parece válido."); return false; }
+    if(!data.consent){ showErr("Debes aceptar para recibir el diagnóstico."); return false; }
+  }
+  return true;
+}
+
+function nextQ(){
+  if(!validate()) return;
+  const qs = visibleQuestions();
+  if(step < qs.length - 1){ step++; renderQ(); }
+  else { document.getElementById("wz-bar").style.width = "100%"; runAnalysis(); }
+}
+function prevQ(){ if(step>0){ step--; renderQ(); } }
+
+/* ================= ANALYSIS ANIMATION (RF-3) ================= */
+const AN_STEPS = [
+  "Analizando tu perfil de riesgo",
+  "Cruzando la composición de tu portfolio",
+  "Detectando desajustes y puntos ciegos",
+  "Calculando el coste de tu liquidez parada",
+  "Generando tu plan de acción personalizado"
+];
+function runAnalysis(){
+  show("screen-analyzing");
+  const wrap = document.getElementById("an-steps");
+  wrap.innerHTML = "";
+  AN_STEPS.forEach((s,i)=>{
+    const d = document.createElement("div");
+    d.className = "an-step"; d.id = "an-step-"+i;
+    d.innerHTML = `<span>[${String(i+1).padStart(2,"0")}]&nbsp;&nbsp;${s}</span><span class="st">EN COLA</span>`;
+    wrap.appendChild(d);
+  });
+  let i = 0;
+  const tick = ()=>{
+    if(i>0){ const p=document.getElementById("an-step-"+(i-1)); p.classList.remove("run"); p.classList.add("done"); p.querySelector(".st").textContent="✓ LISTO"; }
+    if(i<AN_STEPS.length){
+      const c=document.getElementById("an-step-"+i); c.classList.add("run"); c.querySelector(".st").textContent="PROCESANDO";
+      i++; setTimeout(tick, 700 + Math.random()*500);
+    } else {
+      setTimeout(()=>{ renderResult(); show("screen-result"); }, 450);
+    }
+  };
+  setTimeout(tick, 350);
+}
+
+/* ================= MOCK DIAGNOSIS ENGINE (RF-4 — en producción lo hace Claude) ================= */
+const RISK_ORDER = ["Muy agresivo","Agresivo","Moderado","Conservador","Muy conservador"];
+const EXP_TXT = ["alguien que empieza de cero","menos de un año de experiencia","entre 1 y 3 años en el mercado","más de 3 años en el mercado"];
+const money = n => n.toLocaleString("es-ES");
+
+function buildDiagnosis(d){
+  const p = d.portfolio;
+  const capital = rangeMid(d.capital), cash = rangeMid(d.cash), monthly = rangeMidM(d.monthly);
+  const investedPct = p.btc + p.eth + p.alt;            // % del portfolio realmente expuesto
+  const parkedPct = p.stables + p.fiat;                 // % parado
+  const riskIdx = d.risk;                                // 0 muy agresivo … 4 muy conservador
+  const exposureMismatch = (riskIdx >= 3 && p.alt + p.eth*0.5 > 30);   // conservador con mucho riesgo
+  const timidMismatch = (riskIdx <= 1 && investedPct < 50);            // agresivo casi sin exposición
+  const altSpread = d.altcoins !== undefined ? [1.5,4,8,12][d.altcoins] : 0;
+  const parkedUSD = Math.round(capital * parkedPct / 100);
+  const hotLead = (cash >= CONFIG.hotLeadMinUSD) || (capital >= 100000);
+
+  /* --- Sec.1: situación real --- */
+  let s1 = `<p>${d.name}, vamos con números. Declaras <strong>${RANGES_CAPITAL[d.capital].toLowerCase()}</strong> invertidos en cripto, otros <strong>${RANGES_CAPITAL[d.cash].toLowerCase()}</strong> en efectivo o stablecoins listos para entrar, y una aportación mensual sostenible de <strong>${RANGES_MONTHLY[d.monthly].toLowerCase()}</strong>.</p>
+  <p>Tu portfolio se reparte así: <em>${p.btc}% Bitcoin · ${p.eth}% Ethereum · ${p.stables}% stablecoins · ${p.alt}% altcoins · ${p.fiat}% sin invertir</em>. Te defines como inversor <strong>${RISK_ORDER[d.risk].toLowerCase()}</strong>, con ${EXP_TXT[d.experience]}.</p>`;
+
+  /* --- Sec.2: desajuste principal --- */
+  let mismatchHTML = "";
+  if(exposureMismatch){
+    mismatchHTML = `<div class="warning"><div class="box-tag">El desajuste principal</div>
+      <p style="color:#ffd0d0;font-size:.98rem;line-height:1.7">Dices ser <strong>${RISK_ORDER[d.risk].toLowerCase()}</strong>, pero tu portfolio no lo refleja: entre altcoins y parte de tu ETH cargas con una exposición de riesgo alta. Ser conservador con un portfolio agresivo no es prudencia: es un desajuste que se paga en la próxima caída. Tu cartera y tu perfil están peleados, y uno de los dos miente.</p></div>`;
+  } else if(timidMismatch){
+    mismatchHTML = `<div class="warning"><div class="box-tag">El desajuste principal</div>
+      <p style="color:#ffd0d0;font-size:.98rem;line-height:1.7">Dices ser <strong>${RISK_ORDER[d.risk].toLowerCase()}</strong>, pero solo tienes el ${investedPct}% del portfolio realmente expuesto. No es un problema de riesgo: es un problema de ejecución. Tienes convicción declarada y una cartera que no la sigue.</p></div>`;
+  } else {
+    mismatchHTML = `<div class="callout"><div class="box-tag">Tu desajuste principal</div>
+      <p>Tu perfil declarado (${RISK_ORDER[d.risk].toLowerCase()}) y tu exposición real (${investedPct}% invertido) están razonablemente alineados. Tu problema no es de coherencia: es de <strong>estructura</strong> — y eso es más fácil de arreglar.</p></div>`;
+  }
+  if(altSpread >= 6){
+    mismatchHTML += `<p>Tienes <strong>${altSpread >= 12 ? "más de 10" : "entre 6 y 10"} altcoins distintas</strong>. Eso no es diversificar, es dispersar: ninguna posición individual es lo bastante grande para mover tu resultado, pero todas juntas sí son lo bastante grandes para destrozarlo si el mercado se gira. El 80% de ese riesgo no te está pagando nada.</p>`;
+  }
+
+  /* --- Sec.3: coste de la liquidez (gancho comercial clave del audio) --- */
+  let liqHTML;
+  if(parkedPct >= 20){
+    liqHTML = `<div class="callout"><div class="box-tag">El coste de estar parado</div>
+      <p>Tienes el <strong>${parkedPct}% de tu portfolio sin trabajar</strong> — alrededor de <strong>${money(parkedUSD)} $</strong> entre stablecoins y fiat, más otros <strong>${RANGES_CAPITAL[d.cash].toLowerCase()}</strong> disponibles para entrar. Tu mayor riesgo ahora mismo no es que el mercado caiga: es <em>quedarte fuera</em> si el movimiento que esperabas ocurre sin ti. Cada mes que pasa, ese capital parado tiene un coste de oportunidad que no aparece en ningún extracto.</p></div>`;
+  } else if(parkedPct > 0){
+    liqHTML = `<div class="callout"><div class="box-tag">Tu liquidez</div>
+      <p>Mantienes un ${parkedPct}% en reserva (${money(parkedUSD)} $ aprox.) — razonable como colchón táctico. La pregunta es si ese colchón tiene un <strong>plan de despliegue</strong> con niveles concretos, o si es solo miedo disfrazado de paciencia.</p></div>`;
+  } else {
+    liqHTML = `<div class="callout"><div class="box-tag">Tu liquidez</div>
+      <p>Estás <strong>100% invertido</strong>. Eso elimina el riesgo de quedarte fuera, pero te deja sin munición: si el mercado te regala una corrección, no podrás aprovecharla más que con tu aportación mensual.</p></div>`;
+  }
+
+  /* --- Sec.4: plan de acción --- */
+  const plan = [];
+  if(d.experience === 0){
+    plan.push("Antes de tocar nada: estructura. Tu primer paso no es comprar, es definir cuánto va a BTC (tu base), cuánto a ETH y un máximo estricto para altcoins. Sin esa arquitectura, cada compra es una apuesta aislada.");
+  }
+  if(parkedPct >= 20){
+    plan.push(`Define hoy un plan de despliegue para tu liquidez: 3 niveles de entrada escalonados (por ejemplo, 40% ahora / 30% en corrección / 30% en confirmación). Lo que no tiene plan, no se ejecuta.`);
+  }
+  if(altSpread >= 6){
+    plan.push(`Consolida tus altcoins: quédate con tus 2–3 posiciones de mayor convicción y rota el resto hacia BTC/ETH. Menos líneas, más tamaño, más control.`);
+  }
+  if(exposureMismatch){
+    plan.push(`Reequilibra hacia tu perfil real: si eres ${RISK_ORDER[d.risk].toLowerCase()}, tu peso en BTC+ETH debería ser claramente dominante. Ajusta posiciones, no emociones.`);
+  }
+  if(monthly > 0){
+    plan.push(`Automatiza tu aportación de ${RANGES_MONTHLY[d.monthly].toLowerCase()}/mes con DCA: misma cantidad, mismo día, sin decidir. La disciplina gana al timing.`);
+  }
+  if(plan.length < 3) plan.push("Documenta tu tesis: escribe en qué escenario compras más, en cuál no haces nada y en cuál reduces. La decisión tiene que existir antes de que el mercado se mueva, no después.");
+
+  /* --- Hot lead flag (solo visible en consola/prototipo — en prod va a Formspree) --- */
+  if(hotLead) console.info("[MOCK] 🔥 LEAD CALIENTE:", d.name, "| capital:", RANGES_CAPITAL[d.capital], "| cash:", RANGES_CAPITAL[d.cash]);
+
+  return { s1, mismatchHTML, liqHTML, plan, hotLead, parkedPct, parkedUSD };
+}
+
+/* ================= RENDER RESULT ================= */
+function renderResult(){
+  const dx = buildDiagnosis(data);
+  const name = data.name || "inversor";
+
+  document.getElementById("res-content").innerHTML = `
+    <div class="res-sec">
+      <div class="sec-head"><span class="idx">01</span><h3>Tu situación real, ${name}</h3></div>
+      <div class="prose">${dx.s1}</div>
+    </div>
+
+    <div class="res-sec">
+      <div class="sec-head"><span class="idx">02</span><h3>El desajuste principal</h3></div>
+      ${dx.mismatchHTML}
+    </div>
+
+    <div class="res-sec">
+      <div class="sec-head"><span class="idx">03</span><h3>El coste de tu liquidez parada</h3></div>
+      ${dx.liqHTML}
+    </div>
+
+    <div class="res-sec">
+      <div class="sec-head"><span class="idx">04</span><h3>Tu plan de acción</h3></div>
+      <div class="plan-list">
+        ${dx.plan.map((p,i)=>`<div class="plan-item"><span class="pn">${String(i+1).padStart(2,"0")}</span><p>${p}</p></div>`).join("")}
+      </div>
+    </div>
+
+    <div class="res-sec">
+      <div class="sec-head"><span class="idx">05</span><h3>Tu regalo: el contexto completo</h3></div>
+      <div class="video-box">
+        <div class="video-ph">
+          <div class="play">▶</div>
+          <div class="vt">Video exclusivo · solo para quienes completan el diagnóstico</div>
+        </div>
+        <div class="video-cap">[PROTOTIPO] Aquí se embebe el video regalo (YouTube no listado) — SPEC §11.6</div>
+      </div>
+    </div>
+
+    <div class="cta">
+      <div class="cta-eyebrow">El siguiente paso</div>
+      <h3>Este diagnóstico es la foto.<br><em>Ahora toca la película.</em></h3>
+      <p>Si quieres que revisemos tu caso en directo — tu portfolio concreto, tus niveles y tu plan de despliegue — agenda una llamada con el equipo. Sin compromiso, con números.</p>
+      <button class="btn-gold" style="animation:none" onclick="alert('[PROTOTIPO] CTA → ${CONFIG.ctaText}\\nEn producción: Calendly o WhatsApp (SPEC §11.7)')">${CONFIG.ctaText} →</button>
+    </div>`;
+
+  document.getElementById("res-footer").innerHTML =
+    `${CONFIG.brand.toUpperCase()} · Documento educativo · No constituye asesoramiento financiero personalizado.<br>
+     <span style="color:#3d3c37">[PROTOTIPO] En producción: lead → Formspree · diagnóstico → Claude API vía Cloudflare Worker</span>`;
+}
+</script>
+</body>
+</html>

