/* Script de captura para el prototipo — abre index.html, completa el wizard con un caso de prueba y captura pantallas.
   Uso: chrome --headless ... index.html?shot=wizard|analysis|result */
const params = new URLSearchParams(location.search);
const shot = params.get("shot");
if(shot){
  window.addEventListener("load", ()=> setTimeout(()=>{
    if(shot === "wizard"){
      startWizard();
    }
    if(shot === "portfolio"){
      startWizard();
      data.capital = 2; data.cash = 3; data.monthly = 2; data.risk = 3; data.experience = 1;
      step = 5; renderQ();
    }
    if(shot === "analysis"){
      // rellena todo y lanza análisis
      data.capital = 2; data.cash = 3; data.monthly = 2; data.risk = 3; data.experience = 1;
      data.portfolio = { btc:20, eth:10, stables:15, alt:15, fiat:40 };
      data.altcoins = 3; data.concern = "Compré en máximos y tengo la mitad parada sin saber cuándo entrar.";
      data.name = "Carlos"; data.phone = "+34 600 111 222"; data.email = "carlos@test.com"; data.consent = true;
      runAnalysis();
    }
    if(shot === "result"){
      data.capital = 2; data.cash = 3; data.monthly = 2; data.risk = 3; data.experience = 1;
      data.portfolio = { btc:20, eth:10, stables:15, alt:15, fiat:40 };
      data.altcoins = 3; data.concern = "Compré en máximos y tengo la mitad parada sin saber cuándo entrar.";
      data.name = "Carlos"; data.phone = "+34 600 111 222"; data.email = "carlos@test.com"; data.consent = true;
      renderResult(); show("screen-result");
    }
  }, 600));
}

